"},{"node":"TestSSEHub_Close","qualified_name":"bench-repo.server.router.api.v1.TestSSEHub_Close","label":"Function","file":"server/router/api/v1/sse_hub_test.go","start_line":50,"end_line":70,"in_degree":0,"out_degree":5,"match_lines":[55,56],"source":"func TestSSEHub_Close(t *testing.T) {
	hub := NewSSEHub()
	c1 := hub.Subscribe(1, store.RoleUser)
	c2 := hub.Subscribe(2, store.RoleAdmin)

	hub.Close()
	hub.Close()

	for _, ch := range []chan []byte{c1.events, c2.events} {
		_, ok := <-ch
		assert.False(t, ok, "channel should be closed after hub close")
	}

	late := hub.Subscribe(3, store.RoleUser)
	_, ok := <-late.events
	assert.False(t, ok, "late subscriber should be closed immediately")

	hub.Broadcast(&SSEEvent{Type: SSEEventMemoCreated, Name: "memos/123"})
	hub.Unsubscribe(c1)
	hub.Unsubscribe(late)
}
"},{"node":"TestTranscribe","qualified_name":"bench-repo.server.router.api.v1.test.TestTranscribe","label":"Function","file":"server/router/api/v1/test/ai_service_test.go","start_line":16,"end_line":284,"in_degree":0,"out_degree":11,"match_lines":[52,60,106,163,213],"source":"func TestTranscribe(t *testing.T) {
